import{_ as r,a0 as p,w as o,s as u,I as t,x as a,a1 as l,A as e,ao as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"在 Linux 上安裝 VMware 工具 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上安裝 VMware 工具 | LCTT (201910) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上安裝 VMware 工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上安裝 VMware 工具 | LCTT (201910) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201910/20190301 Guide to Install VMware Tools on Linux","title":"在 Linux 上安裝 VMware 工具","tag":"201910","desc":""},"relativePath":"201910/20190301 Guide to Install VMware Tools on Linux.md","filePath":"[post].md"}'),w={name:"201910/20190301 Guide to Install VMware Tools on Linux.md"};function d(m,s,V,f,M,g){const n=p("Link");return o(),u("div",null,[s[24]||(s[24]=t("h1",{id:"在-linux-上安裝-vmware-工具",tabindex:"-1"},[a("在 Linux 上安裝 VMware 工具 "),t("a",{class:"header-anchor",href:"#在-linux-上安裝-vmware-工具","aria-label":"Permalink to “在 Linux 上安裝 VMware 工具”"},"​")],-1)),s[25]||(s[25]=t("blockquote",null,[t("p",null,"VMware 工具通過允許你共享剪貼板和文件夾以及其他東西來提升你的虛擬機體驗。瞭解如何在 Ubuntu 和其它 Linux 發行版上安裝 VMware 工具。")],-1)),s[26]||(s[26]=t("p",null,[t("img",{src:"https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/03/install-vmware-tools-linux.png?resize=800%2C450&ssl=1",alt:"如何在 Linux 上安裝 VMware 工具"})],-1)),t("p",null,[s[1]||(s[1]=a("在先前的教程中，你學習了",-1)),l(n,{href:"https://itsfoss.com/install-vmware-player-ubuntu-1310/"},{default:e(()=>[...s[0]||(s[0]=[a("在 Ubuntu 上安裝 VMware 工作站",-1)])]),_:1}),s[2]||(s[2]=a("。你還可以通過安裝 VMware 工具進一步提升你的虛擬機功能。",-1))]),t("p",null,[s[4]||(s[4]=a("如果你已經在 VMware 上安裝了一個訪客機系統，你必須要注意 ",-1)),l(n,{href:"https://kb.vmware.com/s/article/340"},{default:e(()=>[...s[3]||(s[3]=[a("VMware 工具",-1)])]),_:1}),s[5]||(s[5]=a("的要求 —— 儘管並不完全清楚到底有什麼要求。",-1))]),s[27]||(s[27]=i('<p>在本文中，我們將要強調 VMware 工具的重要性、所提供的特性，以及在 Ubuntu 和其它 Linux 發行版上安裝 VMware 工具的方法。</p><h3 id="vmware-工具-概覽及特性" tabindex="-1">VMware 工具：概覽及特性 <a class="header-anchor" href="#vmware-工具-概覽及特性" aria-label="Permalink to “VMware 工具：概覽及特性”">​</a></h3><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/02/vmware-tools-downloading.jpg?fit=800%2C531&amp;ssl=1" alt="在 Ubuntu 上安裝 VMware 工具"></p><p>出於顯而易見的理由，虛擬機（你的訪客機系統）並不能做到與宿主機上的表現完全一致。在其性能和操作上會有特定的限制。那就是為什麼引入 VMware 工具的原因。</p><p>VMware 工具以一種高效的形式在提升了其性能的同時，也可以幫助管理訪客機系統。</p><h4 id="vmware-工具到底負責什麼" tabindex="-1">VMware 工具到底負責什麼？ <a class="header-anchor" href="#vmware-工具到底負責什麼" aria-label="Permalink to “VMware 工具到底負責什麼？”">​</a></h4><p>你大致知道它可以做什麼，但讓我們探討一下細節：</p><ul><li>同步訪客機系統與宿主機系統間的時間以簡化操作</li><li>提供從宿主機系統向訪客機系統傳遞消息的能力。比如説，你可以複製文字到剪貼板，並將它輕鬆粘貼到你的訪客機系統</li><li>在訪客機系統上啓用聲音</li><li>提升訪客機視頻分辨率</li><li>修正錯誤的網絡速度數據</li><li>減少不合適的色深</li></ul><p>在訪客機系統上安裝了 VMware 工具會給它帶來顯著改變，但是它到底包含了什麼特性才解鎖或提升這些功能的呢？讓我們來看看……</p><h4 id="vmware-工具-核心特性細節" tabindex="-1">VMware 工具：核心特性細節 <a class="header-anchor" href="#vmware-工具-核心特性細節" aria-label="Permalink to “VMware 工具：核心特性細節”">​</a></h4><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/02/vmware-tools-features.gif?resize=800%2C500&amp;ssl=1" alt="用 VMware 工具在宿主機系統與訪客機系統間共享剪切板"></p><p>如果你不想知道它包含什麼來啓用這些功能的話，你可以跳過這部分。但是為了好奇的讀者，讓我們簡短地討論它一下：</p><p><strong>VMware 設備驅動：</strong> 它具體取決於操作系統。大多數主流操作系統都默認包含了設備驅動，因此你不必另外安裝它。這主要涉及到內存控制驅動、鼠標驅動、音頻驅動、網卡驅動、VGA 驅動以及其它。</p><p><strong>VMware 用户進程：</strong> 這是這裏真正有意思的地方。通過它你獲得了在訪客機和宿主機間複製粘貼和拖拽的能力。基本上，你可以從宿主機複製粘貼文本到虛擬機，反之亦然。</p><p>你同樣也可以拖拽文件。此外，在你未安裝 SVGA 驅動時它會啓用鼠標指針的釋放/鎖定。</p><p><strong>VMware 工具生命週期管理：</strong> 嗯，我們會在下面看看如何安裝 VMware 工具，但是這個特性幫你在虛擬機中輕鬆安裝/升級 VMware 工具。</p><p><strong>共享文件夾</strong>：除了這些。VMware 工具同樣允許你在訪客機與宿主機系統間共享文件夾。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2019/02/vmware-tools-shared-folder.jpg?fit=800%2C660&amp;ssl=1" alt="使用 VMware 工具在訪客機與宿機系統間共享文件"></p><p>當然，它的效果同樣取決於訪客機系統。例如在 Windows 上你通過 Unity 模式運行虛擬機上的程序並從宿主機系統上操作它。</p><h3 id="如何在-ubuntu-和其它-linux-發行版上安裝-vmware-工具" tabindex="-1">如何在 Ubuntu 和其它 Linux 發行版上安裝 VMware 工具 <a class="header-anchor" href="#如何在-ubuntu-和其它-linux-發行版上安裝-vmware-工具" aria-label="Permalink to “如何在 Ubuntu 和其它 Linux 發行版上安裝 VMware 工具”">​</a></h3><p><strong>注意：</strong> 對於 Linux 操作系統，你應該已經安裝好了“Open VM 工具”，大多數情況下免除了額外安裝 VMware 工具的需要。</p>',21)),t("p",null,[s[7]||(s[7]=a("大部分時候，當你安裝了訪客機系統時，如果操作系統支持 ",-1)),l(n,{href:"https://docs.vmware.com/en/VMware-Workstation-Player-for-Linux/15.0/com.vmware.player.linux.using.doc/GUID-3F6B9D0E-6CFC-4627-B80B-9A68A5960F60.html"},{default:e(()=>[...s[6]||(s[6]=[a("Easy Install",-1)])]),_:1}),s[8]||(s[8]=a(" 的話你會收到軟件更新或彈窗告訴你要安裝 VMware 工具。",-1))]),s[28]||(s[28]=i(`<p>Windows 和 Ubuntu 都支持 Easy Install。因此如果你使用 Windows 作為你的宿主機或嘗試在 Ubuntu 上安裝 VMware 工具，你應該會看到一個和彈窗消息差不多的選項來輕鬆安裝 VMware 工具。這是它應該看起來的樣子：</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/02/vmware-tools.jpg?fit=800%2C481&amp;ssl=1" alt="安裝 VMware 工具的彈窗"></p><p>這是搞定它最簡便的辦法。因此當你配置虛擬機時確保你有一個通暢的網絡連接。</p><p>如果你沒收到任何彈窗或者選項來輕鬆安裝 VMware 工具。你需要手動安裝它。以下是如何去做：</p><ol><li><p>運行 VMware Workstation Player。</p></li><li><p>從菜單導航至 “Virtual Machine -&gt; Install VMware tools”。如果你已經安裝了它並想修復安裝，你會看到 “Re-install VMware tools” 這一選項出現。</p></li><li><p>一旦你點擊了，你就會看到一個虛擬 CD/DVD 掛載在訪客機系統上。</p></li><li><p>打開該 CD/DVD，並複製粘貼那個 tar.gz 文件到任何你選擇的區域並解壓，這裏我們選擇“桌面”作為解壓目的地。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2019/02/vmware-tools-extraction.jpg?fit=800%2C564&amp;ssl=1" alt=""></p></li><li><p>在解壓後，運行終端並通過輸入以下命令導航至裏面的文件夾：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span></span></span></code></pre></div></li></ol><p>cd Desktop/VMwareTools-10.3.2-9925305/vmware-tools-distrib</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span></span></span>
<span class="line"><span>    你需要檢查文件夾與路徑名，這取決於版本與解壓目的地，名字可能會改變。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    ![][10]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    用你的存儲位置（如“下載”）替換“桌面”，如果你安裝的也是 10.3.2 版本，其它的保持一樣即可。</span></span>
<span class="line"><span>6. 現在僅需輸入以下命令開始安裝：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    \`\`\`</span></span>
<span class="line"><span>sudo ./vmware-install.pl -d</span></span></code></pre></div><pre><code>![][11]

你會被詢問密碼以獲得安裝權限，輸入密碼然後應當一切都搞定了。
</code></pre><p>到此為止了，你搞定了。這系列步驟應當適用於幾乎大部分基於 Ubuntu 的訪客機系統。如果你想要在 Ubuntu 服務器上或其它系統安裝 VMware 工具，步驟應該類似。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>在 Ubuntu Linux 上安裝 VMware 工具應該挺簡單。除了簡單辦法，我們也詳述了手動安裝的方法。如果你仍需幫助或者對安裝有任何建議，在評論區評論讓我們知道。</p><hr>`,12)),t("p",null,[s[10]||(s[10]=a("via: ",-1)),l(n,{href:"https://itsfoss.com/install-vmware-tools-linux"},{default:e(()=>[...s[9]||(s[9]=[a("https://itsfoss.com/install-vmware-tools-linux",-1)])]),_:1})]),t("p",null,[s[15]||(s[15]=a("作者：",-1)),l(n,{href:"https://itsfoss.com/author/ankush/"},{default:e(()=>[...s[11]||(s[11]=[a("Ankush Das",-1)])]),_:1}),s[16]||(s[16]=a(" 選題：",-1)),l(n,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[12]||(s[12]=[a("lujun9972",-1)])]),_:1}),s[17]||(s[17]=a(" 譯者：",-1)),l(n,{href:"https://github.com/tomjlw"},{default:e(()=>[...s[13]||(s[13]=[a("tomjlw",-1)])]),_:1}),s[18]||(s[18]=a(" 校對：",-1)),l(n,{href:"https://github.com/wxy"},{default:e(()=>[...s[14]||(s[14]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[21]||(s[21]=a("本文由 ",-1)),l(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[19]||(s[19]=[a("LCTT",-1)])]),_:1}),s[22]||(s[22]=a(" 原創編譯，",-1)),l(n,{href:"https://linux.cn/"},{default:e(()=>[...s[20]||(s[20]=[a("Linux中國",-1)])]),_:1}),s[23]||(s[23]=a(" 榮譽推出",-1))])])}const k=r(w,[["render",d]]);export{h as __pageData,k as default};
